  ('Which HTTP method is typically used to create a new resource in a REST API?', '["GET","DELETE","PUT","POST"]'::jsonb, 3, true, ARRAY['COMPS','CSE','AIDS']::text[], 2, 4, 2, 'POST creates a new resource.'),
