  ('What does GAN stand for in machine learning?', '["Generative Adversarial Network","General Artificial Neuron","Gradient Adjusted Network","Graph Attention Node"]'::jsonb, 0, true, ARRAY['COMPS','CSE','AIDS']::text[], 3, 4, 2, 'Two networks compete: generator and discriminator.'),
  ('In a confusion matrix, precision is:', '["TP / (TP + FN)","TP / (TP + FP)","(TP + TN) / total","TN / (TN + FP)"]'::jsonb, 1, true, ARRAY['COMPS','CSE','AIDS']::text[], 3, 4, 3, 'Precision = correct positives among predicted positives.'),
