  ('Dropout in neural networks mainly helps reduce:', '["Underfitting","Slow GPUs","Data leakage","Overfitting"]'::jsonb, 3, true, ARRAY['COMPS','CSE','AIDS']::text[], 3, 4, 3, 'Randomly dropping units prevents co-adaptation.'),
