SELECT
  count(*) as total_seeded_questions,
  count(CASE WHEN 'ALL' = ANY(branches) THEN 1 END) as general_tech_count,
  count(CASE WHEN 'ALL' != ALL(branches) THEN 1 END) as branch_specific_count
FROM public.questions;
